package com.pulsesg.support.controller; import com.pulsesg.support.dto.ApiDtos.*; import com.pulsesg.support.service.PortalService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/users/me") public class UserController {private final PortalService s;public UserController(PortalService s){this.s=s;}public record Update(@NotBlank String fullName){}@GetMapping UserResponse get(){return s.user(s.current());}@PutMapping UserResponse update(@Valid @RequestBody Update r){return s.user(s.updateProfile(r.fullName()));}}
